 const command=(label,run)=>{const b=root.ownerDocument.createElement('button');b.type='button';b.textContent=label;b.title=label;b.setAttribute('aria-label',label);b.dataset.editorCommand=label;b.addEventListener('mousedown',e=>e.preventDefault());b.addEventListener('click',()=>{run(view.state,view.dispatch,view);view.focus();});group.append(b);controls.push({button:b,run,label,table:['Add row','Add column','Remove row','Remove column','Remove table'].includes(label)});};
