 section('Text');command('Paragraph',setBlockType(editorSchema.nodes.paragraph));for(const level of [2,3])command('H'+level,setBlockType(editorSchema.nodes.heading,{level}));for(const name of ['strong','em','code'])command({strong:'Bold',em:'Italic',code:'Value / code'}[name],toggleMark(editorSchema.marks[name]));section('Structure');command('Bullets',wrapInList(editorSchema.nodes.bullet_list));command('Numbered list',wrapInList(editorSchema.nodes.ordered_list));command('Link',(state,dispatch)=>{if(!dispatch)return true;const href=root.ownerDocument.defaultView.prompt('HTTPS address, site path or section anchor');if(href===null)return false;if(!href)return toggleMark(editorSchema.marks.link)(state,dispatch);if(!contentURL(href))return false;return toggleMark(editorSchema.marks.link,{href:contentURL(href)})(state,dispatch);});
