 refresh();return {view,refresh,setNode:(path,node,{addToHistory=true}={})=>{let parent=view.state.doc,pos=0;for(let depth=0;depth<path.length;depth++){for(let i=0;i<path[depth];i++)pos+=parent.child(i).nodeSize;parent=parent.child(path[depth]);if(depth<path.length-1)pos++;}view.dispatch(view.state.tr.replaceWith(pos,pos+parent.nodeSize,editorSchema.nodeFromJSON(node)).setMeta('addToHistory',addToHistory));},setDocument:(doc)=>{view.dispatch(view.state.tr.replaceWith(0,view.state.doc.content.size,editorSchema.nodeFromJSON(doc).content).setMeta('addToHistory',false));},resetHistory:()=>{view.updateState(EditorState.create({schema:editorSchema,doc:view.state.doc,selection:view.state.selection,plugins:view.state.plugins}));refresh();},get:()=>canonicalNode(view.state.doc.toJSON()),destroy:()=>{view.destroy();root.replaceChildren();}};
